/**
 * Save / delete listing images in the uploads/ folder.
 *  - Detects the image type from its "magic bytes" (the first bytes of the file), NOT the file extension
 *    or the Content-Type sent by the browser -> renaming a .php file to .jpg does not get through.
 *  - File names are random UUIDs generated by the server -> no collisions, no overwrites, not guessable.
 */
import { randomUUID } from 'node:crypto';
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
export const UPLOAD_DIR = path.join(ROOT_DIR, 'uploads');
const LISTING_SUBDIR = 'listings';

/**
 * Read the file signature to find the image type.
 * @param {Buffer} buf
 * @returns {'jpg'|'png'|'webp'|null}
 */
export function detectImageType(buf) {
  if (buf.length < 12) return null;
  // JPEG: FF D8 FF
  if (buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) return 'jpg';
  // PNG: 89 50 4E 47 0D 0A 1A 0A
  if (buf.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) return 'png';
  // WebP: "RIFF" .... "WEBP"
  if (buf.toString('ascii', 0, 4) === 'RIFF' && buf.toString('ascii', 8, 12) === 'WEBP') return 'webp';
  return null;
}

/**
 * Write the images to disk.
 * @param {{ buffer: Buffer, ext: string }[]} images
 * @returns {Promise<string[]>} relative paths stored in the DB, e.g. "listings/3f2a....webp"
 */
export async function saveListingImages(images) {
  const dir = path.join(UPLOAD_DIR, LISTING_SUBDIR);
  await fs.mkdir(dir, { recursive: true });

  const saved = [];
  try {
    for (const { buffer, ext } of images) {
      const relative = `${LISTING_SUBDIR}/${randomUUID()}.${ext}`;
      // flag 'wx': fail if the file already exists instead of overwriting it
      await fs.writeFile(path.join(UPLOAD_DIR, relative), buffer, { flag: 'wx' });
      saved.push(relative);
    }
    return saved;
  } catch (err) {
    await removeImages(saved); // partially written -> clean up what was written
    throw err;
  }
}

/**
 * Delete images (missing files are ignored). Only files inside uploads/ can be deleted.
 * @param {string[]} relativePaths
 */
export async function removeImages(relativePaths) {
  await Promise.allSettled(
    relativePaths.map(async (relative) => {
      const full = path.resolve(UPLOAD_DIR, relative);
      // Block paths like "../../.env" escaping the uploads folder
      if (!full.startsWith(UPLOAD_DIR + path.sep)) return;
      await fs.rm(full, { force: true });
    }),
  );
}
